// Neumann's principle by exact group action (FIG-01-06 Neumann machine; C01 manuscript Sec. 7).
// A generic tensor with the property's intrinsic index symmetry is averaged over the group generated by the selected operations
// (Reynolds operator, applied to the FULL tensor, then contracted with the Voigt factors of tensors.ts; weis1985 p. 198: apply
// Neumann's principle to the full tensor, then contract). The invariant subspace is reduced to row echelon form with a column
// priority that puts the conventional independent names first; every other Voigt component is classified as zero, equal, minus,
// a multiple, or a linear combination of the independents. Tolerance 1e-12.
// Frame: IEEE Std 176-1987 for 3m (constants.ts FRAME): x perpendicular to a mirror plane, z the threefold axis.
import type { Mat3, Vec3 } from "./linalg.ts";
import { matMul3 } from "./linalg.ts";
import { rotateTensor2, rotateTensor3, rotateTensor4, voigtToTensor3, voigtToTensor4, tensor3ToVoigt, tensor4ToVoigt, rotZ } from "./tensors.ts";
import type { Matrix, Tensor } from "./tensors.ts";

export interface SymOp {
  id: string;
  label: string;
  R: Mat3;
}
const mirror = (nx: number, ny: number): Mat3 => [
  [1 - 2 * nx * nx, -2 * nx * ny, 0],
  [-2 * nx * ny, 1 - 2 * ny * ny, 0],
  [0, 0, 1],
];
/** The six operations of 3m in the IEEE frame. Mirror normals at 0 deg (the yz plane), +60 deg and -60 deg from x. */
export function groupOps3m(): SymOp[] {
  const c = Math.cos(Math.PI / 3);
  const s = Math.sin(Math.PI / 3);
  return [
    { id: "E", label: "identity", R: [[1, 0, 0], [0, 1, 0], [0, 0, 1]] },
    { id: "C3", label: "120 deg about z", R: rotZ((2 * Math.PI) / 3) },
    { id: "C3^2", label: "240 deg about z", R: rotZ((4 * Math.PI) / 3) },
    { id: "m_yz", label: "mirror yz (normal x)", R: mirror(1, 0) },
    { id: "m_p60", label: "mirror, normal at +60 deg from x", R: mirror(c, s) },
    { id: "m_m60", label: "mirror, normal at -60 deg from x", R: mirror(c, -s) },
  ];
}

const matEq = (A: Mat3, B: Mat3, tol = 1e-9): boolean => A.every((r, i) => r.every((v, j) => Math.abs(v - B[i][j]) < tol));
/** Closure of a set of orthogonal matrices under multiplication (identity always included). */
export function closeGroup(gens: readonly Mat3[]): Mat3[] {
  const G: Mat3[] = [[[1, 0, 0], [0, 1, 0], [0, 0, 1]]];
  const add = (M: Mat3) => {
    if (!G.some((g) => matEq(g, M))) G.push(M);
  };
  gens.forEach(add);
  for (let changed = true; changed; ) {
    changed = false;
    const n = G.length;
    for (let i = 0; i < n; i++)
      for (let j = 0; j < n; j++) {
        const P = matMul3(G[i], G[j]);
        if (!G.some((g) => matEq(g, P))) {
          G.push(P);
          changed = true;
        }
      }
    if (G.length > 48) throw new Error("group closure exceeded 48 elements (not a point group)");
  }
  return G;
}

export type PropertyKind = "pyro" | "eps" | "d" | "e" | "r" | "c" | "s" | "p";
interface KindInfo {
  rank: 1 | 2 | 3 | 4;
  rows: number;
  cols: number;
  /** independent generic parameters given the intrinsic index symmetry */
  generic: number;
  sym: string;
  prefer: string[];
}
export const KINDS: Record<PropertyKind, KindInfo> = {
  pyro: { rank: 1, rows: 1, cols: 3, generic: 3, sym: "p", prefer: ["p3"] },
  eps: { rank: 2, rows: 3, cols: 3, generic: 6, sym: "eps", prefer: ["eps11", "eps33"] },
  d: { rank: 3, rows: 3, cols: 6, generic: 18, sym: "d", prefer: ["d15", "d22", "d31", "d33"] },
  e: { rank: 3, rows: 3, cols: 6, generic: 18, sym: "e", prefer: ["e15", "e22", "e31", "e33"] },
  r: { rank: 3, rows: 6, cols: 3, generic: 18, sym: "r", prefer: ["r13", "r22", "r33", "r51"] },
  c: { rank: 4, rows: 6, cols: 6, generic: 21, sym: "c", prefer: ["c11", "c12", "c13", "c14", "c33", "c44"] },
  s: { rank: 4, rows: 6, cols: 6, generic: 21, sym: "s", prefer: ["s11", "s12", "s13", "s14", "s33", "s44"] },
  p: { rank: 4, rows: 6, cols: 6, generic: 36, sym: "p", prefer: ["p11", "p12", "p13", "p14", "p31", "p33", "p41", "p44"] },
};
const name = (kind: PropertyKind, i: number, j: number): string => {
  const k = KINDS[kind];
  if (kind === "pyro") return `p${j + 1}`;
  return `${k.sym}${i + 1}${j + 1}`;
};

/** Generic parameter basis in Voigt form: one Voigt matrix per independent intrinsic-symmetry parameter. */
function genericBasis(kind: PropertyKind): Matrix[] {
  const k = KINDS[kind];
  const out: Matrix[] = [];
  const zero = (): Matrix => Array.from({ length: k.rows }, () => new Array(k.cols).fill(0));
  for (let i = 0; i < k.rows; i++)
    for (let j = 0; j < k.cols; j++) {
      const symmetric = kind === "eps" || kind === "c" || kind === "s";
      if (symmetric && j < i) continue;
      const M = zero();
      M[i][j] = 1;
      if (symmetric) M[j][i] = 1;
      out.push(M);
    }
  return out;
}

function toTensor(kind: PropertyKind, M: Matrix): Tensor {
  if (kind === "pyro") return Float64Array.from(M[0]);
  if (kind === "eps") return Float64Array.from(M.flat());
  if (kind === "d" || kind === "e" || kind === "r") return voigtToTensor3(M, kind);
  return voigtToTensor4(M, kind);
}
function fromTensor(kind: PropertyKind, T: Tensor): Matrix {
  if (kind === "pyro") return [Array.from(T)];
  if (kind === "eps") return [Array.from(T.slice(0, 3)), Array.from(T.slice(3, 6)), Array.from(T.slice(6, 9))];
  if (kind === "d" || kind === "e" || kind === "r") return tensor3ToVoigt(T, kind);
  return tensor4ToVoigt(T, kind);
}
function rotate(kind: PropertyKind, T: Tensor, R: Mat3): Tensor {
  const r = KINDS[kind].rank;
  if (r === 1) return Float64Array.from([0, 1, 2].map((i) => R[i][0] * T[0] + R[i][1] * T[1] + R[i][2] * T[2]));
  if (r === 2) return rotateTensor2(T, R);
  if (r === 3) return rotateTensor3(T, R);
  return rotateTensor4(T, R);
}

/** Reynolds average of a full tensor (rank 1-4, polar) over the group generated by `ops`. */
export function symmetrize(T: Tensor, rank: 1 | 2 | 3 | 4, ops: readonly Mat3[]): Tensor {
  const G = closeGroup(ops);
  const out = new Float64Array(T.length);
  const kind: PropertyKind = rank === 1 ? "pyro" : rank === 2 ? "eps" : rank === 3 ? "e" : "c";
  for (const g of G) {
    const Tg = rotate(kind, T, g);
    for (let i = 0; i < out.length; i++) out[i] += Tg[i] / G.length;
  }
  return out;
}

export type RelationClass = "zero" | "independent" | "equal" | "minus" | "factor" | "combination";
export interface Relation {
  name: string;
  row: number;
  col: number;
  cls: RelationClass;
  /** coefficients on the independent names (empty for zero and independent) */
  terms: { name: string; coef: number }[];
  text: string;
}
export interface NeumannResult {
  kind: PropertyKind;
  groupOrder: number;
  independent: string[];
  independentCount: number;
  genericCount: number;
  relations: Relation[][];
}

function frac(x: number): [number, number] {
  for (let q = 1; q <= 12; q++) {
    const p = Math.round(x * q);
    if (Math.abs(p / q - x) < 1e-9) return [p, q];
  }
  return [x, 1];
}
function relText(lhs: string, terms: { name: string; coef: number }[]): string {
  if (terms.length === 0) return `${lhs} = 0`;
  const fr = terms.map((t) => frac(t.coef));
  const exact = fr.every(([, q], i) => Number.isInteger(fr[i][0]) && q <= 12);
  if (!exact) return `${lhs} = ${terms.map((t) => `${t.coef >= 0 ? "+" : "-"}${Math.abs(t.coef).toPrecision(6)} ${t.name}`).join(" ")}`;
  const L = fr.reduce((m, [, q]) => (m * q) / gcd(m, q), 1);
  let nums = fr.map(([p, q]) => (p * L) / q);
  const g = terms.length > 1 ? nums.reduce((m, v) => gcd(m, Math.abs(v)), 0) : 1;
  if (g > 1) nums = nums.map((v) => v / g);
  const pre = g > 1 ? `${g}` : "";
  let body = "";
  nums.forEach((n, i) => {
    const s = n < 0 ? "-" : body ? "+" : "";
    const a = Math.abs(n);
    body += `${body ? ` ${s} ` : s}${a === 1 ? "" : a}${terms[i].name}`;
  });
  if (L === 1) return g > 1 ? `${lhs} = ${pre}(${body})` : `${lhs} = ${body}`;
  return `${lhs} = ${pre}${terms.length > 1 ? `(${body})` : body}/${L}`;
}
const gcd = (a: number, b: number): number => (b === 0 ? Math.abs(a) : gcd(b, a % b));

/** Allowed form of a property tensor under the group generated by `ops`: independent components, count, and relations. */
export function neumann(kind: PropertyKind, ops: readonly Mat3[], prefer: string[] = KINDS[kind].prefer, tol = 1e-12): NeumannResult {
  const k = KINDS[kind];
  const G = closeGroup(ops);
  const rowsV: number[][] = [];
  for (const B of genericBasis(kind)) {
    const T = toTensor(kind, B);
    const S = new Float64Array(T.length);
    for (const g of G) {
      const Tg = rotate(kind, T, g);
      for (let i = 0; i < S.length; i++) S[i] += Tg[i] / G.length;
    }
    rowsV.push(fromTensor(kind, S).flat());
  }
  // column order: preferred names first, then row-major
  const n = k.rows * k.cols;
  const names = Array.from({ length: n }, (_, idx) => name(kind, Math.floor(idx / k.cols), idx % k.cols));
  const order: number[] = [];
  for (const p of prefer) {
    const i = names.indexOf(p);
    if (i >= 0 && !order.includes(i)) order.push(i);
  }
  for (let i = 0; i < n; i++) if (!order.includes(i)) order.push(i);
  // RREF over permuted columns
  const A = rowsV.map((r) => order.map((c) => r[c]));
  const pivots: number[] = [];
  let row = 0;
  for (let col = 0; col < n && row < A.length; col++) {
    let best = row;
    for (let i = row + 1; i < A.length; i++) if (Math.abs(A[i][col]) > Math.abs(A[best][col])) best = i;
    if (Math.abs(A[best][col]) < 1e-10) continue;
    [A[row], A[best]] = [A[best], A[row]];
    const pv = A[row][col];
    for (let j = 0; j < n; j++) A[row][j] /= pv;
    for (let i = 0; i < A.length; i++) {
      if (i === row) continue;
      const f = A[i][col];
      if (f !== 0) for (let j = 0; j < n; j++) A[i][j] -= f * A[row][j];
    }
    pivots.push(col);
    row++;
  }
  const indepNames = pivots.map((pc) => names[order[pc]]);
  const rel: Relation[][] = Array.from({ length: k.rows }, () => []);
  for (let pc = 0; pc < n; pc++) {
    const idx = order[pc];
    const r = Math.floor(idx / k.cols);
    const c = idx % k.cols;
    const nm = names[idx];
    let rec: Relation;
    const pivRow = pivots.indexOf(pc);
    if (pivRow >= 0) rec = { name: nm, row: r, col: c, cls: "independent", terms: [], text: nm };
    else {
      // component value = sum over pivots p of A[p][pc] * value(pivot p)
      const terms = pivots.map((_, p) => ({ name: indepNames[p], coef: A[p][pc] })).filter((t) => Math.abs(t.coef) > tol * 1e3);
      let cls: RelationClass;
      if (terms.length === 0) cls = "zero";
      else if (terms.length > 1) cls = "combination";
      else if (Math.abs(terms[0].coef - 1) < 1e-9) cls = "equal";
      else if (Math.abs(terms[0].coef + 1) < 1e-9) cls = "minus";
      else cls = "factor";
      rec = { name: nm, row: r, col: c, cls, terms, text: relText(nm, terms) };
    }
    rel[r][c] = rec;
  }
  return { kind, groupOrder: G.length, independent: indepNames, independentCount: pivots.length, genericCount: k.generic, relations: rel };
}

/** Elements of the group generated by `ops` that leave the vector E unchanged, and the point-group name of that subgroup
 *  (Curie's principle; C01 manuscript Sec. 7 L3). E = [0, 0, 0] keeps the full group. */
export function stabilizer(ops: readonly Mat3[], E: Vec3, tol = 1e-9): { ops: Mat3[]; name: string } {
  const G = closeGroup(ops);
  const keep = G.filter((g) => [0, 1, 2].every((i) => Math.abs(g[i][0] * E[0] + g[i][1] * E[1] + g[i][2] * E[2] - E[i]) < tol));
  return { ops: keep, name: groupName(keep) };
}
/** Name of a subgroup of 3m from its elements: "1", "m", "3", "3m"; otherwise "order-N". */
export function groupName(G: readonly Mat3[]): string {
  const det = (M: Mat3) => M[0][0] * (M[1][1] * M[2][2] - M[1][2] * M[2][1]) - M[0][1] * (M[1][0] * M[2][2] - M[1][2] * M[2][0]) + M[0][2] * (M[1][0] * M[2][1] - M[1][1] * M[2][0]);
  const nMirror = G.filter((g) => det(g) < 0).length;
  if (G.length === 1) return "1";
  if (G.length === 2 && nMirror === 1) return "m";
  if (G.length === 3 && nMirror === 0) return "3";
  if (G.length === 6 && nMirror === 3) return "3m";
  return `order-${G.length}`;
}
